import React from 'react';
import {createRoot} from 'react-dom/client';
import Sidebar from '/src/components/VideoSyncPhysiologySidebar.jsx';
import {CivetPlot} from '/src/components/CivetCard.jsx';
import '/src/index.css';
import './video-sidebar-refinements.css';
const rows=Array.from({length:1501},(_,i)=>({time_offset_s:i,baseline_hr:88,hr:88+Math.min(26,i*.025)+7*Math.sin(i/28)+2*Math.sin(i/4),hrv_rmssd_ms:15-4*Math.sin(i/90),hrv_sdnn_ms:31+6*Math.cos(i/80),hr_source:'direct_h10',signal_confidence_score:95,hrv_quality:'high'}));
const pressure=Array.from({length:301},(_,i)=>{const t=i/10;return {t,pressure_kpa:.3+Array.from({length:6},(_,n)=>1.9*Math.exp(-(((t-(10+n*.9))/.22)**2))).reduce((a,b)=>a+b,0)}});
function Pressure({big=false,onInspect}){return <section className={'pressure '+(big?'big':'')}><header><b>PELVIC PRESSURE</b><button className="badge" onClick={onInspect}>Reference uncertain ⓘ</button></header><div className="pressure-values"><div><strong>2.3 <small>kPa</small></strong><span>Pressure rise</span></div><div><strong>6</strong><span>Peaks in selected burst</span></div><div><strong>5.4 <small>s</small></strong><span>Burst duration</span></div></div><div className="pressure-graph"><CivetPlot rows={pressure} start={0} end={30} layers={{raw:true}}/></div><footer><span>0:00</span><span>0:10</span><span>0:20</span><span>0:30</span></footer><div className="pressure-bottom"><span>Pressure peaks visible · relative intensity unavailable</span><button onClick={onInspect}>Inspect burst →</button></div></section>}

const configs=[{id:'a',title:'A · Minimal cleanup',sub:'Existing order. Controls moved. Phase card stays intact.'},{id:'b',title:'B · Tighter phase card',sub:'Same evidence and curves. Less header space; taller trends.'},{id:'c',title:'C · Wider sidebar',sub:'Same cards. More horizontal room instead of smaller text.'}];
function Column({config}){return <div className={'mock-column '+config.id}><div className="mock-heading"><h1>{config.title}</h1><p>{config.sub}</p></div><div className="refined-sidebar"><div className="native"><Sidebar timelineRows={rows} playheadS={994} xDomain={[844,1144]} zoomWindow={300} onZoomWindowChange={()=>{}} onSeek={()=>{}} bloodPressureReadings={[{time_offset_s:910,systolic:144,diastolic:105}]} compact resizable phaseSession={{}} optionalChannels={{respiration:false,motion:false,civet:false}}/></div><Pressure onInspect={()=>{}}/></div><div className="player-controls"><div><b>16:34</b><button>−5s</button><button className="play">▶ Play</button><button>+5s</button><button>1× ▾</button></div><div><span>Graph window</span><button>5m ▾</button><button>Channels ▾</button><button>Voice ▾</button></div><small>Numpad 1–9 → 1×–9× · controls below the video</small></div></div>}
function App(){const selected=new URLSearchParams(location.search).get('variant');return <div className="refinement-stage"><div className="mock-label">SARAH · SIDEBAR REFINEMENTS · ACTUAL COMPONENTS, ILLUSTRATIVE DATA · VIDEO AREA UNCHANGED</div><div className="columns">{configs.filter(c=>!selected||c.id===selected).map(c=><Column key={c.id} config={c}/>)}</div></div>};
createRoot(document.getElementById('root')).render(<App/>);
